export function renderIllustration(id, to) {
  const item = illustrations[id];
  if (!item) return '';
  const path = to(`assets/illustrations/${item.file}`);
  return `![${item.alt}](${path})\n\n*${item.caption}*\n\n[Open the illustration at full size](${path}).`;
}
